"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[16640],{77060:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponIK","desc":"Holds a two-hand weapon with two IKControls, on every player character this\\nclient sees. The hold animations store only joint rotations, so on an avatar\\nwith other proportions the weapon and the left hand go to other places.\\n- Right hand: pinned to `HoldAnimConfig.RightHand[name]` (shoulder space),\\n  so the weapon sits where it sits on the block rig, relative to the shoulder.\\n  The offset scales by the arm reach against `HoldAnimConfig.BlockReach`.\\n- Left hand: pulled to `HoldAnimConfig.LeftHand[name]` (Handle space),\\n  solved after the right hand, so it lands on the moved weapon.\\n`name` = `HoldAnimConfig.holdName(tool)`. The player\'s weapon pose (`WeaponPose`\\nattribute; for the local player the editor preview wins) moves all three points\\nthrough `WeaponPose`, and a change applies at once. The right-hand target stays\\nwithin `WeaponPoseConfig.ReachCap` of the measured arm reach.\\nThe server (`ToolGripService`) sizes a pose weapon and sets its grip for everyone; for\\nthe local player this script also previews the size and the grip of the unsaved pose,\\none-hand weapons (`WeaponPoseConfig.OneHand`, no IK) included.\\nBoth IKs have `SmoothTime` 0 (stiff hold). `AimPose` measures the gun at the\\nright-hand target, not at the hand, because the IK lags the bend by a frame.\\nBoth IKs are off while a Reload track plays, because the reloads move the hands on purpose.\\nIf the forend is out of reach of a short arm, the target slides back along\\nthe weapon toward the right hand (each frame), so the arm does not overstretch.\\nWhile the IKs hold a weapon, the arms\' BallSocketConstraints are off: their\\nlimits stop the hand short of the target, so it drifts with the walk.","realm":["Client"],"source":{"line":29,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponIK.client.luau"}}')}}]);